"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["70256"],{25187(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_cascata_remanejamento.ordem_invalida","status":422,"titulo":"A ordem do destino deve ser \u2265 1"},"descricao":{"codigo":"uniplus.selecao.configuracao_cascata_remanejamento.ordem_invalida","requisitos":["UNI-REQ-0056"],"oQueAconteceu":["O campo `ordem` de uma posi\xe7\xe3o da cascata \xe9 menor que 1. A ordem \xe9 a\\nposi\xe7\xe3o do destino na fila de remanejamento daquela origem \u2014 a vaga n\xe3o\\npreenchida \xe9 oferecida ao primeiro destino, depois ao segundo, e assim por\\ndiante; n\xe3o existe posi\xe7\xe3o zero ou negativa.","Pode coexistir, no mesmo item, com\\n[`codigo_invalido`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.codigo_invalido)\\n(at\xe9 duas ocorr\xeancias, uma por c\xf3digo) \u2014 as confer\xeancias do item s\xe3o\\nindependentes entre si e acumulam (ADR-0125). Acumula tamb\xe9m com os\\nmesmos erros de outros itens da lista `destinos`, e, quando algum item\\nfalha, com as causas de fallback e de limites de origens/destinos que n\xe3o\\ndependem de os itens serem v\xe1lidos \u2014 ver\\n[`campos_obrigatorios`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.campos_obrigatorios)."],"comoResolver":["Corrija `ordem` para um n\xfamero inteiro maior ou igual a 1. Se a inten\xe7\xe3o\\nera reordenar os destinos da mesma origem, renumere a sequ\xeancia inteira a\\npartir de 1, sem pular nem repetir posi\xe7\xf5es."],"ondeAparece":["Defini\xe7\xe3o de cascata de remanejamento do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao cascata remanejamento"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);